/* 데이터통신 추가 문항 (9주차: 6장 링크 계층과 LAN, 10주차: 1장 컴퓨터 네트워크와 인터넷). 모든 문항은 src 쪽 내용에 근거하며 계산은 직접 확인했다. */
(window.EXAM_BANK=window.EXAM_BANK||[]).push(
{id:'dc-s01',course:'data-communication',src:['dc09',4],type:'short',q:'링크 계층의 패킷(2계층 패킷)을 부르는 이름은?',answer:['프레임','frame'],why:'9주차 4쪽: 2계층 패킷 = 프레임(frame), datagram을 캡슐화.'},
{id:'dc-s02',course:'data-communication',src:['dc09',8],type:'short',q:'링크 계층이 주로 구현되는 장치(약어 3글자)는?',answer:['NIC','network interface card','네트워크 인터페이스 카드','어댑터'],why:'9주차 8쪽: 어댑터(NIC) 또는 칩.'},
{id:'dc-s03',course:'data-communication',src:['dc09',15],type:'short',q:'D = 101110, G = 1001일 때 CRC 나머지 R은?',answer:['011'],why:'101110000 ÷ 1001 (modulo 2)의 나머지 = 011.'},
{id:'dc-s04',course:'data-communication',src:['dc09',15],type:'short',q:'D = 1101, G = 101일 때 CRC 나머지 R은? (r = 2)',answer:['10'],why:'110100 ÷ 101 (modulo 2): 110⊕101 → 011100, 111⊕101 → 001000, 100⊕101 → 000010 → 나머지 10. 전송 110110, 검산 110110 ÷ 101 나머지 00.'},
{id:'dc-s05',course:'data-communication',src:['dc09',14],type:'short',q:'CRC 생성자 G가 r+1비트일 때 반드시 검출할 수 있는 burst 오류의 최대 길이는? (r을 사용해 답)',answer:['r+1','r + 1','r+1비트'],why:'9주차 14쪽: 모든 r+1 bit 이하의 burst 오류를 검출.'},
{id:'dc-s06',course:'data-communication',src:['dc09',26],type:'short',q:'노드가 매우 많을 때 slotted ALOHA의 최대 효율은? (소수 둘째 자리)',answer:['0.37','1/e','37%'],why:'9주차 26쪽: max efficiency = 1/e ≈ .37.'},
{id:'dc-s07',course:'data-communication',src:['dc09',28],type:'short',q:'노드가 매우 많을 때 순수 ALOHA의 최대 효율은? (소수 둘째 자리)',answer:['0.18','1/(2e)','1/2e','18%'],why:'9주차 28쪽: 1/(2e) = .18.'},
{id:'dc-s08',course:'data-communication',src:['dc09',33],type:'short',q:'Ethernet CSMA/CD에서 4번째 연속 충돌 후 K를 고르는 범위의 최댓값은?',answer:['15'],why:'m = 4 → {0, …, 2^4 − 1} = {0, …, 15}.'},
{id:'dc-s09',course:'data-communication',src:['dc09',33],type:'short',q:'이진 백오프에서 K를 골랐을 때 기다리는 시간은 K × 몇 비트 시간인가?',answer:['512','512비트','512 비트 시간'],why:'9주차 33쪽: K·512 bit 시간 동안 기다림.'},
{id:'dc-s10',course:'data-communication',src:['dc09',42],type:'short',q:'대부분의 LAN에서 MAC 주소는 몇 비트인가?',answer:['48','48비트'],why:'9주차 42쪽: 48 bit MAC 주소.'},
{id:'dc-s11',course:'data-communication',src:['dc09',46],type:'short',q:'ARP 질의 프레임의 목적지 MAC 주소는?',answer:['FF-FF-FF-FF-FF-FF','FFFFFFFFFFFF','ff-ff-ff-ff-ff-ff','ff:ff:ff:ff:ff:ff'],why:'9주차 46쪽: 브로드캐스트 주소.'},
{id:'dc-s12',course:'data-communication',src:['dc09',45],type:'short',q:'ARP 테이블 항목의 TTL은 보통 몇 분인가?',answer:['20','20분'],why:'9주차 45쪽: 보통 20분.'},
{id:'dc-s13',course:'data-communication',src:['dc09',55],type:'short',q:'Ethernet 프리앰블의 마지막 바이트 비트 패턴은?',answer:['10101011'],why:'9주차 55쪽: 10101010 7바이트 + 10101011 1바이트.'},
{id:'dc-s14',course:'data-communication',src:['dc09',74],type:'short',q:'802.1Q 태그의 TPID(Tag Protocol Identifier) 값은? (16진수)',answer:['81-00','8100','0x8100','81 00'],why:'9주차 74쪽: value 81-00.'},
{id:'dc-s15',course:'data-communication',src:['dc09',74],type:'short',q:'802.1Q 태그의 VLAN ID 필드는 몇 비트인가?',answer:['12','12비트'],why:'9주차 74쪽: 12 bit VLAN ID field.'},
{id:'dc-s16',course:'data-communication',src:['dc09',80],type:'short',q:'진입 MPLS 라우터가 하류 라우터의 MPLS 포워딩을 설정할 때 쓰는 신호 프로토콜은?',answer:['RSVP-TE','RSVPTE','RSVP TE'],why:'9주차 80쪽.'},
{id:'dc-s17',course:'data-communication',src:['dc09',40],type:'short',q:'802.11 무선 LAN이 사용하는 MAC 프로토콜은?',answer:['CSMA/CA','CSMACA'],why:'9주차 40쪽: 802.11에 사용되는 CSMA/CA.'},
{id:'dc-s18',course:'data-communication',src:['dc09',12],type:'short',q:'데이터 1011001에 짝수 parity 비트를 붙이면 parity 비트 값은?',answer:['0'],why:'1의 개수가 4개(짝수)이므로 parity 비트는 0.'},
{id:'dc-t01',course:'data-communication',src:['dc09',11],type:'tf',q:'오류 검출 비트(EDC)를 사용하면 모든 비트 오류를 반드시 검출할 수 있다.',answer:false,why:'9주차 11쪽: 오류 검출을 100% 신뢰할 수 있는 것은 아니다.'},
{id:'dc-t02',course:'data-communication',src:['dc09',12],type:'tf',q:'2차원 비트 parity는 단일 비트 오류를 검출하고 정정할 수 있다.',answer:true,why:'9주차 12쪽.'},
{id:'dc-t03',course:'data-communication',src:['dc09',21],type:'tf',q:'TDMA에서는 활성 노드가 하나뿐이면 그 노드가 채널 전체 속도 R을 사용할 수 있다.',answer:false,why:'고정 슬롯만 쓰므로 R/N만 사용합니다(9주차 21, 35쪽).'},
{id:'dc-t04',course:'data-communication',src:['dc09',30],type:'tf',q:'CSMA를 사용하면 전파 지연이 있어도 충돌이 일어나지 않는다.',answer:false,why:'9주차 30쪽: 전파 지연 때문에 충돌은 여전히 생길 수 있다.'},
{id:'dc-t05',course:'data-communication',src:['dc09',31],type:'tf',q:'충돌 감지(CD)는 무선 LAN보다 유선 LAN에서 쉽다.',answer:true,why:'9주차 31쪽.'},
{id:'dc-t06',course:'data-communication',src:['dc09',44],type:'tf',q:'IP 주소는 평면 구조라 노드를 다른 서브넷으로 옮겨도 그대로 쓸 수 있다.',answer:false,why:'평면 구조로 이동성이 있는 것은 MAC 주소입니다. IP는 계층적이라 서브넷에 의존합니다(9주차 44쪽).'},
{id:'dc-t07',course:'data-communication',src:['dc09',46],type:'tf',q:'ARP 질의에 대한 응답은 질의한 노드에게 유니캐스트로 보내진다.',answer:true,why:'9주차 46쪽: B는 A에게 자신의 MAC 주소를 응답, 프레임이 A의 MAC 주소로 전송(unicast).'},
{id:'dc-t08',course:'data-communication',src:['dc09',50],type:'tf',q:'datagram이 라우터를 지나 다른 LAN으로 갈 때 프레임의 MAC 주소는 바뀌지만 datagram의 출발지·목적지 IP 주소는 그대로이다.',answer:true,why:'9주차 48~51쪽.'},
{id:'dc-t09',course:'data-communication',src:['dc09',57],type:'tf',q:'Ethernet 수신 NIC는 프레임을 정상 수신하면 송신 NIC에 ACK를 보낸다.',answer:false,why:'Ethernet은 비신뢰적이라 ACK/NAK를 보내지 않습니다(9주차 57쪽).'},
{id:'dc-t10',course:'data-communication',src:['dc09',63],type:'tf',q:'스위치는 프레임의 목적지 MAC 주소를 이용해 자가 학습한다.',answer:false,why:'출발지 MAC 주소와 들어온 인터페이스를 학습합니다(9주차 63쪽).'},
{id:'dc-t11',course:'data-communication',src:['dc09',69],type:'tf',q:'스위치와 라우터는 모두 저장 후 전달(store-and-forward) 장치이다.',answer:true,why:'9주차 69쪽.'},
{id:'dc-t12',course:'data-communication',src:['dc09',77],type:'tf',q:'MPLS 라우터는 레이블 값만으로 출력 인터페이스를 결정하며 IP 주소를 검사하지 않는다.',answer:true,why:'9주차 77쪽.'},
{id:'dc-c01',course:'data-communication',src:['dc09',64],type:'code',q:'빈 스위치 테이블에서 A(포트 1)가 C(포트 3)로 프레임을 보낸 직후 스위치 테이블에 생기는 항목을 "MAC 포트" 형식으로 쓰시오.',code:'스위치 포트: A=1, B=2, C=3, D=4\n프레임 1: A → C',answer:['A 1','A1','A,1'],why:'출발지 A와 들어온 포트 1만 학습합니다. C는 아직 모릅니다(flood).'},
{id:'dc-c02',course:'data-communication',src:['dc09',64],type:'code',q:'이어서 C가 A에게 응답하면, 스위치가 이 프레임을 내보내는 포트 번호는?',code:'스위치 테이블: A → 1\n프레임 2: C(포트 3) → A',answer:['1','1번'],why:'A의 위치(포트 1)를 알고 있으므로 1번 포트로만 전달합니다. 동시에 C → 3을 학습합니다.'},
{id:'dc-c03',course:'data-communication',src:['dc09',81],type:'code',q:'자료의 MPLS 표에서 R4가 레이블 10을 붙여 보낸 A행 패킷이 R3을 지난 뒤 갖는 레이블은?',code:'R3: in 10 → out 6, A, if 1\n    in 12 → out 9, D, if 0',answer:['6'],why:'R3 테이블: 입력 10 → 출력 6.'},
{id:'dc-c04',course:'data-communication',src:['dc09',13],type:'code',q:'16비트 단어 1111 1111 0000 0000 과 0000 0001 0000 0001 의 인터넷 checksum은? (16비트, 공백 없이)',code:'  1111111100000000\n+ 0000000100000001\n= ?  (자리올림은 다시 더함)\nchecksum = 합의 1의 보수',answer:['1111111111111101'],why:'합 0xFF00 + 0x0101 = 1 0000 0000 0000 0001 → 올림 1을 다시 더해 0000 0000 0000 0010 → 1의 보수 1111 1111 1111 1101.'},
{id:'dc-s19',course:'data-communication',src:['dc10',19],type:'short',q:'L = 12,000비트 패킷을 R = 3 Mbps 링크로 내보내는 전송 지연은 몇 ms인가?',answer:['4', '4ms'],why:'10주차 19쪽: L/R = 12,000 / 3,000,000 = 0.004 s = 4 ms.'},
{id:'dc-s20',course:'data-communication',src:['dc10',25],type:'short',q:'L = 7.5 Mbits, R = 1.5 Mbps, 출발지–라우터–목적지(링크 2개)일 때 저장 후 전달 종단간 지연은 몇 초인가? (전파·처리·큐잉 무시)',answer:['10', '10초'],why:'10주차 25쪽: 2L/R = 2 × 5 s = 10 s.'},
{id:'dc-s21',course:'data-communication',src:['dc10',45],type:'short',q:'링크 길이 2,000 km, 전파 속도 2×10^8 m/s일 때 전파 지연은 몇 ms인가?',answer:['10', '10ms'],why:'10주차 45쪽: d/s = 2×10^6 m ÷ 2×10^8 m/s = 0.01 s = 10 ms.'},
{id:'dc-s22',course:'data-communication',src:['dc10',45],type:'short',q:'전송 지연 d_trans를 패킷 길이 L과 링크 대역폭 R로 나타내시오.',answer:['L/R'],why:'10주차 45쪽: d_trans = L/R.'},
{id:'dc-s23',course:'data-communication',src:['dc10',45],type:'short',q:'전파 지연 d_prop를 링크 길이 d와 전파 속도 s로 나타내시오.',answer:['d/s'],why:'10주차 45쪽: d_prop = d/s.'},
{id:'dc-s24',course:'data-communication',src:['dc10',48],type:'short',q:'L = 1,000 bits, a = 800 패킷/초, R = 1 Mbps일 때 트래픽 강도 La/R은?',answer:['0.8', '.8', '4/5', '80%'],why:'10주차 48쪽: 1,000 × 800 / 1,000,000 = 0.8.'},
{id:'dc-s25',course:'data-communication',src:['dc10',53],type:'short',q:'서버 링크 Rs = 2 Mbps, 클라이언트 링크 Rc = 1 Mbps일 때 종단간 평균 처리율은 몇 Mbps인가?',answer:['1', '1Mbps'],why:'10주차 53쪽: min(Rs, Rc) = 1 Mbps.'},
{id:'dc-s26',course:'data-communication',src:['dc10',54],type:'short',q:'Rs = 3 Mbps, Rc = 2 Mbps, 백본 R = 10 Mbps를 10개 연결이 공정하게 공유할 때 연결당 처리율은 몇 Mbps인가?',answer:['1', '1Mbps'],why:'10주차 54쪽: min(Rc, Rs, R/10) = min(2, 3, 1) = 1 Mbps.'},
{id:'dc-s27',course:'data-communication',src:['dc10',30],type:'short',q:'1 Mb/s 링크에서 각 사용자가 활동 시 100 kb/s를 쓸 때, 회선 교환으로 수용할 수 있는 최대 사용자 수는?',answer:['10', '10명'],why:'10주차 30쪽: 1,000 kb/s ÷ 100 kb/s = 10명.'},
{id:'dc-s28',course:'data-communication',src:['dc10',34],type:'short',q:'ISP 10개를 모두 서로 직접 연결할 때 필요한 연결 수는?',answer:['45', '45개'],why:'10주차 34쪽 O(N²): N(N−1)/2 = 10 × 9 / 2 = 45.'},
{id:'dc-s29',course:'data-communication',src:['dc10',6],type:'short',q:'인터넷 표준 문서를 부르는 이름(약어)은?',answer:['RFC', 'Request for Comments'],why:'10주차 6쪽: RFC: Request for comments.'},
{id:'dc-s30',course:'data-communication',src:['dc10',6],type:'short',q:'인터넷 표준을 만드는 기구(약어)는?',answer:['IETF', 'Internet Engineering Task Force'],why:'10주차 6쪽: IETF.'},
{id:'dc-s31',course:'data-communication',src:['dc10',62],type:'short',q:'네트워크 계층 헤더 Hn이 붙은 데이터 단위의 이름은?',answer:['datagram', '데이터그램'],why:'10주차 62쪽: Hn Ht M = datagram.'},
{id:'dc-s32',course:'data-communication',src:['dc10',62],type:'short',q:'트랜스포트 계층 헤더 Ht가 붙은 데이터 단위의 이름은?',answer:['segment', '세그먼트'],why:'10주차 62쪽: Ht M = segment.'},
{id:'dc-s33',course:'data-communication',src:['dc10',61],type:'short',q:'OSI 모델에서 데이터 교환 동기화, 체크포인트, 복구를 담당하는 계층은?',answer:['session', '세션', '세션계층', 'session layer'],why:'10주차 61쪽: session: 데이터 교환의 동기화, 체크포인트, 복구.'},
{id:'dc-s34',course:'data-communication',src:['dc10',13],type:'short',q:'DSL에서 전화국(중앙국)에 있으며 데이터는 인터넷으로, 음성은 전화망으로 보내는 장비는?',answer:['DSLAM'],why:'10주차 13쪽.'},
{id:'dc-s35',course:'data-communication',src:['dc10',46],type:'short',q:'자동차 대열 비유(10대, 요금소 12초/대, 100 km/h, 요금소 간 100 km)에서 대열 전체가 다음 요금소에 도착하는 데 걸리는 시간은 몇 분인가?',answer:['62', '62분'],why:'10주차 46쪽: 전송 120초(2분) + 전파 60분 = 62분.'},
{id:'dc-s36',course:'data-communication',src:['dc10',70],type:'short',q:'1972년 등장한 최초의 호스트 간(host-host) 프로토콜은?',answer:['NCP'],why:'10주차 70쪽.'},
{id:'dc-s37',course:'data-communication',src:['dc10',49],type:'short',q:'traceroute가 경로상의 라우터 i마다 보내는 탐색 패킷 수는?',answer:['3', '3개'],why:'10주차 49쪽.'},
{id:'dc-t13',course:'data-communication',src:['dc10',15],type:'tf',q:'케이블 망(HFC)에서 각 가정은 cable headend까지의 선을 공유한다.',answer:true,why:'10주차 15쪽: 각 가정은 cable headend까지 공유. DSL은 중앙국까지 전용.'},
{id:'dc-t14',course:'data-communication',src:['dc10',20],type:'tf',q:'광섬유는 비유도(unguided) 매체이다.',answer:false,why:'10주차 20쪽: 유도 매체 = 구리선, 광섬유, 동축 케이블. 비유도 = 라디오.'},
{id:'dc-t15',course:'data-communication',src:['dc10',25],type:'tf',q:'저장 후 전달 방식에서 라우터는 패킷의 첫 비트를 받자마자 다음 링크로 전송을 시작한다.',answer:false,why:'10주차 25쪽: 전체 패킷이 도착해야 다음 링크로 전송.'},
{id:'dc-t16',course:'data-communication',src:['dc10',27],type:'tf',q:'전달(forwarding)은 출발지–목적지 경로 전체를 결정하는 전역적 동작이다.',answer:false,why:'10주차 27쪽: 경로 결정은 라우팅(routing). 전달은 입력 패킷을 적절한 출력으로 보내는 동작.'},
{id:'dc-t17',course:'data-communication',src:['dc10',28],type:'tf',q:'회선 교환에서 call이 쉬고 있으면 그 회선을 다른 call이 사용한다.',answer:false,why:'10주차 28쪽: 전용 자원, 공유되지 않음. call이 쉬면 회선도 논다.'},
{id:'dc-t18',course:'data-communication',src:['dc10',45],type:'tf',q:'전송 지연(L/R)은 링크의 물리적 길이에 비례한다.',answer:false,why:'10주차 45쪽: 전송 지연은 L/R로 길이와 무관. 길이에 비례하는 것은 전파 지연 d/s.'},
{id:'dc-t19',course:'data-communication',src:['dc10',48],type:'tf',q:'트래픽 강도 La/R이 1보다 크면 평균 큐잉 지연은 무한대가 된다.',answer:true,why:'10주차 48쪽.'},
{id:'dc-t20',course:'data-communication',src:['dc10',53],type:'tf',q:'종단간 처리율은 경로상의 병목 링크 용량에 의해 결정된다.',answer:true,why:'10주차 53쪽: 병목 링크 = 종단간 처리율을 제한하는 링크.'},
{id:'dc-t21',course:'data-communication',src:['dc10',61],type:'tf',q:'인터넷 프로토콜 스택에는 presentation 계층과 session 계층이 없다.',answer:true,why:'10주차 61쪽: 필요하다면 응용 계층에서 구현.'},
{id:'dc-t22',course:'data-communication',src:['dc10',62],type:'tf',q:'자료의 캡슐화 그림에서 스위치는 네트워크 계층(IP 헤더)까지 처리한다.',answer:false,why:'10주차 62쪽: 스위치는 link·physical까지, 라우터가 network까지 처리.'},
{id:'dc-t23',course:'data-communication',src:['dc10',71],type:'tf',q:'Cerf와 Kahn의 인터네트워킹 원칙에는 상태 없는(stateless) 라우터가 포함된다.',answer:true,why:'10주차 71쪽: minimalism·autonomy, best effort, stateless routers, decentralized control.'},
{id:'dc-t24',course:'data-communication',src:['dc10',66],type:'tf',q:'DoS 공격은 송신 주소를 위조한 패킷을 보내는 공격을 말한다.',answer:false,why:'10주차 66·68쪽: DoS는 가짜 트래픽으로 자원을 고갈시키는 공격. 송신 주소 위조는 IP 스푸핑.'},
{id:'dc-c05',course:'data-communication',src:['dc10',25],type:'code',q:'저장 후 전달 방식에서 아래 경로의 종단간 지연은 몇 ms인가? (전파·처리·큐잉 무시)',code:'L = 8,000 bits\nR = 2 Mbps (모든 링크)\n출발지 ─ 라우터1 ─ 라우터2 ─ 목적지   (링크 3개)',answer:['12', '12ms'],why:'링크마다 L/R = 8,000 / 2,000,000 = 4 ms × 3 = 12 ms (10주차 25쪽 N·L/R).'},
{id:'dc-c06',course:'data-communication',src:['dc10',45],type:'code',q:'아래 조건에서 한 홉의 노드 지연 d_nodal은 몇 ms인가?',code:'L = 1,500 bytes, R = 10 Mbps\nd = 200 km, s = 2×10^8 m/s\nd_proc = 0, d_queue = 0',answer:['2.2', '2.2ms'],why:'d_trans = 12,000 bits / 10^7 bps = 1.2 ms, d_prop = 2×10^5 m / 2×10^8 m/s = 1 ms → 2.2 ms (바이트를 비트로 바꾸는 것에 주의).'},
{id:'dc-c07',course:'data-communication',src:['dc10',47],type:'code',q:'선두 차가 요금소2에 도착하는 순간, 요금소1에 아직 남아 있는 차는 몇 대인가?',code:'차 10대, 요금소 처리 1분/대\n속도 1000 km/h, 요금소 간 거리 100 km',answer:['3', '3대'],why:'10주차 47쪽: 선두 차는 1분 처리 + 6분 주행 = 7분에 도착. 그때까지 7대가 처리되어 3대가 남음.'},
{id:'dc-c08',course:'data-communication',src:['dc10',62],type:'code',q:'출발지 호스트의 링크 계층에서 만들어진 프레임의 구성을 앞에서부터 쓰시오. (헤더 기호 사용)',code:'message  = M\nsegment  = Ht M\ndatagram = Hn Ht M\nframe    = ?',answer:['Hl Hn Ht M', 'HlHnHtM'],why:'10주차 62쪽: 링크 헤더 Hl을 앞에 붙여 Hl Hn Ht M.'},
{id:'dc-c09',course:'data-communication',src:['dc10',54],type:'code',q:'16 Mbits 파일을 보내는 데 걸리는 시간은 몇 초인가? (지연 무시)',code:'Rs = 4 Mbps, Rc = 5 Mbps\n백본 R = 20 Mbps를 10개 연결이 공정 공유',answer:['8', '8초'],why:'처리율 = min(4, 5, 20/10 = 2) = 2 Mbps → 16 / 2 = 8초 (10주차 54쪽).'}
);
